                # Extract Morse code
                morse_match = re.search(r'([-./\s]+)\r\n', data)
                if not morse_match:
                    print("Could not find Morse code")
                    break

                morse_code = morse_match.group(1)
                print(f"\nMorse code received: {morse_code}")

                # Decode Morse to numbers
                decoded = decode_morse(morse_code, MORSE_CODE)
                print(f"\nDecoded Morse to ASCII numbers: {decoded}")

                # Convert numbers to characters and join
                decoded_text = ''.join(chr(int(x)) for x in decoded.split())
                lines = decoded_text.split('\n')

                # Process each line
                n = None
                e = None
                c = None

                for line in lines:
                    if line.startswith('TiA9'):
                        n = clean_and_decode_base64(line)
